// Original Korean interpretations for five major cards, Swords and Pentacles.
// Art cells are row-major; all language is reflective rather than predictive.
const ranks = ['ace', 'two', 'three', 'four', 'five', 'six', 'seven', 'eight', 'nine', 'ten', 'page', 'knight', 'queen', 'king'];
const rankNames = ['에이스', '2', '3', '4', '5', '6', '7', '8', '9', '10', '시종', '기사', '여왕', '왕'];
const rankEnglish = ['ACE', 'TWO', 'THREE', 'FOUR', 'FIVE', 'SIX', 'SEVEN', 'EIGHT', 'NINE', 'TEN', 'PAGE', 'KNIGHT', 'QUEEN', 'KING'];
const numerals = ['A', 'II', 'III', 'IV', 'V', 'VI', 'VII', 'VIII', 'IX', 'X', 'P', 'KN', 'Q', 'K'];

function card(meta, guidance, contexts, step, spread) {
  const topics = {}, details = {};
  for (const [topic, [text, example, action]] of Object.entries(contexts)) {
    topics[topic] = text;
    details[topic] = { example, action };
  }
  return { ...meta, message: guidance.summary, guidance, topics, details, step, spread };
}
function major(id, name, english, number, numeral, keyword, color, index) {
  return { id, name, english, number, numeral, keyword, color, arcana: 'major',
    art: { src: './assets/major-extra.webp', columns: 5, rows: 2, index } };
}
function minor(suit, number, keyword) {
  const index = number - 1;
  return { id: `${suit}_${ranks[index]}`, name: `${suit === 'swords' ? '소드' : '펜타클'} ${rankNames[index]}`,
    english: `${rankEnglish[index]} OF ${suit.toUpperCase()}`, number, numeral: numerals[index], keyword,
    color: suit === 'swords' ? '#a8bfdc' : '#bfc990', arcana: 'minor', suit, rank: ranks[index],
    art: { src: `./assets/${suit}.webp`, columns: 7, rows: 2, index } };
}

